/**
 * Verify the request actually came from the Proposal Studio.
 *
 * The webhook URL is not a secret — it sits in an environment variable, in a
 * deploy log, and in this workflow's own definition. So the URL alone must not
 * be enough to make this workflow email a client. Every request carries:
 *
 *   x-koya-timestamp   unix seconds
 *   x-koya-signature   HMAC-SHA256(secret, `${timestamp}.${rawBody}`), hex
 *
 * The timestamp is inside the signed material, which is what stops a captured
 * request being replayed for ever. Anything outside the window is rejected
 * even if the signature is valid.
 *
 * Comparison is constant-time. A byte-by-byte early exit leaks how much of a
 * forged signature was correct, which is enough to recover one.
 */
const crypto = require('crypto');

const TOLERANCE_SECONDS = 300;

const SECRET_NAME = 'IKE_KOYA_WEBHOOK_SECRET';

/**
 * Where the shared secret comes from, and why this is not a one-liner.
 *
 * `$env` is not available on every n8n instance. n8n Cloud has no process
 * environment a workflow can reach, and self-hosted instances ship with
 * `N8N_BLOCK_ENV_ACCESS_IN_NODE=true` by default. On both, TOUCHING `$env`
 * THROWS rather than returning undefined — which is what the "access to env
 * vars denied" error is. A bare `$env.FOO` therefore does not degrade to a
 * missing secret; it kills the node before the fail-closed branch below can
 * run, and the app sees a 500 instead of a 401 it can explain.
 *
 * So both lookups are attempted and both are guarded:
 *
 *   $env   self-hosted, with N8N_BLOCK_ENV_ACCESS_IN_NODE=false
 *   $vars  n8n Cloud and self-hosted alike — Settings → Variables
 *
 * Order matters only for instances that somehow have both, and process
 * environment wins there because it is the one a deploy pipeline sets.
 */
function readSecret(name) {
  try {
    if (typeof $env !== 'undefined' && $env && $env[name]) return String($env[name]);
  } catch (err) {
    // Env access is blocked on this instance. Not fatal — try Variables.
  }
  try {
    if (typeof $vars !== 'undefined' && $vars && $vars[name]) return String($vars[name]);
  } catch (err) {
    // Neither source is readable. Handled by the fail-closed branch below.
  }
  return null;
}

const secret = readSecret(SECRET_NAME);
if (!secret) {
  // Failing closed. A missing secret must never mean "skip the check".
  return [{
    json: {
      ok: false,
      status: 401,
      reason:
        `${SECRET_NAME} is not readable on this n8n instance. Set it as a ` +
        'Variable (Settings \u2192 Variables), or as an environment variable with ' +
        'N8N_BLOCK_ENV_ACCESS_IN_NODE=false. Its value must match ' +
        'N8N_WEBHOOK_SECRET in the application.',
    },
  }];
}

const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || {};

const timestamp = headers['x-koya-timestamp'];
const signature = headers['x-koya-signature'];

if (!timestamp || !signature) {
  return [{ json: { ok: false, status: 401, reason: 'missing signature headers' } }];
}

const age = Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp));
if (!Number.isFinite(age) || age > TOLERANCE_SECONDS) {
  return [{ json: { ok: false, status: 401, reason: `timestamp outside the ${TOLERANCE_SECONDS}s window (age ${age}s)` } }];
}

/**
 * The signature was computed over the exact bytes the app sent. n8n has
 * already parsed the body, so it is re-serialised here — which is safe only
 * because the app builds the payload with JSON.stringify over a plain object
 * with a fixed key order. If either side ever reorders those keys, every
 * request starts failing verification, loudly, rather than silently accepting
 * unverified input.
 */
const raw = JSON.stringify(body);
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`, 'utf8').digest('hex');

const a = Buffer.from(String(signature), 'utf8');
const b = Buffer.from(expected, 'utf8');
const valid = a.length === b.length && crypto.timingSafeEqual(a, b);

if (!valid) {
  return [{ json: { ok: false, status: 401, reason: 'signature mismatch' } }];
}

// Payload shape check. A verified request with a missing field is a bug in the
// caller, and reporting it as 400 rather than crashing the workflow is what
// makes it debuggable from the app's own delivery record.
const required = ['ref', 'proposalId', 'recipient', 'subject', 'bodyText', 'proposalLink', 'idempotencyKey'];
const missing = required.filter((key) => !body[key]);
if (missing.length > 0) {
  return [{ json: { ok: false, status: 400, reason: `payload missing: ${missing.join(', ')}` } }];
}

return [{
  json: {
    ok: true,
    status: 200,
    ref: body.ref,
    proposalId: body.proposalId,
    recipient: body.recipient,
    // Copied on the client email, normally the approver who signed it off.
    // Defaulted rather than required: an older caller that does not send it
    // must not be rejected, and an empty list is a valid answer.
    cc: Array.isArray(body.cc) ? body.cc : [],
    subject: body.subject,
    bodyText: body.bodyText,
    proposalLink: body.proposalLink,
    idempotencyKey: body.idempotencyKey,
    correlationId: body.correlationId || null,
    verifiedAt: new Date().toISOString(),
  },
}];

/**
 * The internal notification, built after the client email has gone.
 *
 * Kept deliberately short. A notification nobody reads is worse than none,
 * because it trains the channel to be ignored — so this is one line of what
 * happened plus the reference needed to find it, and nothing else.
 *
 * The client's email address is NOT included. It is personal data, the channel
 * is wider than the deal team, and the reference is enough to look it up.
 */

/**
 * The payload is read from the node that produced it, by name.
 *
 * `$input` here is the GMAIL RESPONSE — id, threadId, labelIds — because this
 * node sits directly after the send. It carries no `ref`, no `recipient` and
 * no `proposalId`. Reading the notice out of it put `undefined` in the
 * reference line and threw on `recipient.split`, which is the failure this
 * comment exists to stop coming back.
 *
 * Naming the node also survives an edit. A chain that relies on "whatever the
 * previous node emitted" breaks the moment someone inserts a step between the
 * send and this one; `$('Verify signature')` does not.
 */
function verifiedPayload() {
  try {
    return $('Verify signature').first().json || {};
  } catch (err) {
    // Unreachable in the wired workflow, and still guarded. See below.
    return {};
  }
}

const payload = verifiedPayload();

function sentResponse() {
  try {
    return $('Send client email').first().json || {};
  } catch (err) {
    return {};
  }
}

const sent = sentResponse();

const messageId = sent.id || sent.messageId || sent.threadId || 'unknown';
const ref = payload.ref || 'unknown';

/**
 * The domain only, and never the local part.
 *
 * `recipient` is guaranteed present by the shape check in the verify node, so
 * the guard is not about the happy path. It is about what a throw COSTS here:
 * this node runs after the client already has the email, and an exception
 * makes the workflow answer the app with a failure — at which point the app
 * correctly falls over to its own Resend lane and the client receives the
 * proposal twice. A missing internal notification is a nuisance. A duplicate
 * email to a client is something they see.
 */
function recipientDomain(value) {
  if (typeof value !== 'string') return 'their domain';
  const at = value.lastIndexOf('@');
  if (at === -1 || at === value.length - 1) return 'their domain';
  return value.slice(at + 1);
}

const lines = [
  `**Proposal sent** · \`${ref}\``,
  `Delivered to the client contact at ${recipientDomain(payload.recipient)}.`,
  `Message id: \`${messageId}\``,
];

if (payload.correlationId) {
  lines.push(`Correlation: \`${payload.correlationId}\``);
}

return [{
  json: {
    content: lines.join('\n'),
    // Echoed back to the app in the webhook response so the delivery row can
    // record which provider message this was.
    messageId,
    ref,
    proposalId: payload.proposalId || null,
    idempotencyKey: payload.idempotencyKey || null,
  },
}];

/**
 * The failure path.
 *
 * Reached when signature verification fails, the payload is malformed, or
 * Gmail refuses. All three are reported to Discord and returned to the app
 * with a non-2xx status, which is what makes the app fail over to its own
 * Resend lane rather than silently reporting success.
 *
 * The distinction matters: a 401 means somebody sent us an unverifiable
 * request and no email should be attempted anywhere; a 500 means we tried and
 * could not, and the app should try the other lane.
 */
const item = $input.first().json;

/**
 * Two different things arrive here and they carry different fields.
 *
 *   the IF node's false branch   the verify node's refusal: status, reason,
 *                                and no ref, because a request that failed
 *                                verification has no payload we are willing
 *                                to quote back
 *   Gmail's error output         an `error` object, and nothing else at all
 *
 * The second case is why the reference is looked up by node name rather than
 * read off the input. A Gmail failure is the one alert somebody has to act on
 * — the client did not get the proposal — and an alert that says `unknown`
 * where the reference goes cannot be acted on. `Verify signature` still holds
 * the verified payload at this point, so the reference is there to be had.
 *
 * Guarded, because on the 401 path that node produced no payload either, and
 * a notifier that throws turns a reportable failure into a silent one.
 */
function verified() {
  try {
    return $('Verify signature').first().json || {};
  } catch (err) {
    return {};
  }
}

const payload = verified();

const status = item.status || 500;
const reason = item.reason || (item.error && item.error.message) || 'unknown failure';
const ref = item.ref || payload.ref || 'unknown';
const correlationId = item.correlationId || payload.correlationId || null;

const severity = status === 401 ? 'REJECTED' : 'FAILED';

const lines = [
  `**Proposal delivery ${severity}** · \`${ref}\``,
  `Reason: ${reason}`,
];

if (status === 401) {
  lines.push('An unverified request reached this workflow. Nothing was sent. Check that IKE_KOYA_WEBHOOK_SECRET on this n8n instance matches N8N_WEBHOOK_SECRET in the app.');
} else {
  lines.push('The application will fall back to its own send lane. Nothing was sent from here.');
}

if (correlationId) {
  lines.push(`Correlation: \`${correlationId}\``);
}

return [{
  json: {
    content: lines.join('\n'),
    status,
    reason,
    ref,
  },
}];
